      // not trigger directory rescans or hot reloads of the saving application.
      ignored: (candidate: string) => /[/\\]\.diagrams[^/\\]*(?:[/\\]|$)/.test(candidate)
        || candidate === STORAGE_ROOT || candidate.startsWith(STORAGE_ROOT + path.sep)
