107:   private async update(request: StaticAnalysisRequest): Promise<IncrementalResult> {
108:     const started = performance.now(), current = inventory(request);
109:     const selected = new Set(current.selected), previousFiles = new Map<string, string>();
110:     const graphEdges = [...current.edges];
111:     for (const entry of this.checkpoint.fragments) {
112:       for (const file of entry.artifact.snapshot.files) if (file.role === 'analyzed') previousFiles.set(file.path, file.contentHash);
113:       for (const edge of analysisDependencyEdges(entry.artifact)) if (current.local.has(edge[0]) && current.local.has(edge[1])) graphEdges.push(edge);
114:     }
115:     const groups = current.fallback.length ? [[...current.local.keys()].sort()] : dependencyComponents([...current.local.keys()], graphEdges);
116:     const previous = new Map(this.checkpoint.fragments.map(fragment => [fragment.key, fragment]));
117:     const next: IncrementalCheckpoint = { version: 1, fragments: [] }, analyzedFiles: string[] = [], reusedFiles: string[] = [];
118:     for (const members of groups) {
119:       const paths = members.filter(file => selected.has(file)); if (!paths.length) continue;
120:       const key = sha(JSON.stringify([current.environmentKey, paths, members.map(file => [file, current.local.get(file), current.resolutions.get(file)])]));
121:       const cached = previous.get(key);
122:       if (cached) { next.fragments.push(cached); reusedFiles.push(...paths); }
123:       else {
124:         const result = await this.extractor.analyze({ ...request, includePaths: paths });
125:         next.fragments.push({ key, paths, artifact: result.artifact, semanticResolution: result.execution?.semanticResolution ?? true });
126:         analyzedFiles.push(...paths);
127:       }
128:     }
129:     if (!next.fragments.length) throw new Error('Select at least one source file');
130:     // Fresh header pins the current commit/configuration/input set even on a cache hit.
131:     const context = new AnalysisContext(request);
132:     if (next.fragments.some(fragment => fragment.semanticResolution)) void context.checker;
133:     // Module extraction also discovers nested package manifests. They must remain
134:     // pinned even though assembly does not walk declarations again.
135:     const configurationPaths = new Set(context.artifact.snapshot.files.map(file => file.path));
136:     for (const fragment of next.fragments) for (const file of fragment.artifact.snapshot.files) {
137:       if (file.role === 'configuration' && !configurationPaths.has(file.path)) {
138:         context.artifact.snapshot.files.push({ ...file }); configurationPaths.add(file.path);
139:       }
140:     }
141:     const facts = mergeAnalysisFacts(next.fragments.map(fragment => fragment.artifact), selected);
142:     context.entities.clear(); facts.entities.forEach(entity => context.entities.set(entity.id, entity));
143:     facts.relations.forEach(edge => context.relationMap.set(edge.id, edge));
144:     context.artifact.uncertainties = facts.uncertainties;
145:     const artifact = context.finish(); context.release();
146:     deriveAnalysis(artifact, request.metrics, sha);
147:     this.checkpoint = next; // Publish only after a successful complete assembly.
148:     return { artifact, execution: { semanticResolution: next.fragments.some(fragment => fragment.semanticResolution) },
149:       measurements: { elapsedMs: performance.now() - started, peakRssBytes: process.resourceUsage().maxRSS * 1024 },
150:       update: { changedFiles: current.selected.filter(file => previousFiles.get(file) !== current.local.get(file)),
151:         removedFiles: [...previousFiles.keys()].filter(file => !selected.has(file)).sort(), analyzedFiles: analyzedFiles.sort(), reusedFiles: reusedFiles.sort(),
152:         components: next.fragments.length, fallbackReasons: current.fallback, derivedRecomputed: true } };
153:   }

